#include <bits/stdc++.h>
using namespace std;

int main() {
    string s, t;
    cin >> s >> t;

    long long num[10] = {};
    int first = 10;

    for (char c : s) {
        int digit = c - '0';
        ++num[digit];
        if (digit != 0) {
            first = min(first, digit);
        }
    }

    string result;
    if (first < 10) {
        result += char('0' + first);
        --num[first];
    }

    for (int digit = 0; digit < 10; ++digit) {
        result.append(static_cast<size_t>(num[digit]), char('0' + digit));
    }

    cout << (result == t ? "OK" : "WRONG_ANSWER");
    return 0;
}

